IF (SELECT count(*) FROM knowledge_documents d JOIN jsonb_to_recordset('[{"id":"nevora-availability-en","title":"Trial, setup, pricing and end-of-trial choices","url":"https://www.thevelani.com/pages/plans","content":"Jose-confirmed rules, November 9, 2026: NEVORA''s standard trial is free for 30 days with no card and no automatic charge on day 30. It begins when the workplace is provisioned, not at form submission or email verification. Standard setup covers up to 30 employees. Over 30 requires assisted setup and a quote: Velani reviews eligibility; approved teams receive the same 30-day no-card trial starting at provisioning. support@thevelani.com responds to assisted-setup requests within two business days. Do not promise automatic eligibility, instant setup or an activation date. Public self-service signup is not launched yet; use https://www.thevelani.com/pages/contact?interest=nevora-demo until a working signup address is confirmed. At unpaid expiry, operational access is restricted. The Owner retains billing and available payroll exports; employees retain their own available pay statements. Trial expiry starts no automatic workplace-deletion timer. Do not repeat the old three-day deletion claim, promise a future 30-day deletion timer, or promise indefinite storage. Record-retention duties and verified account-deletion requests remain separate. Rondo''s 30-day conversation retention is not workplace retention. Recommend exporting needed records without inventing a deletion deadline. Public commercial prices require confirmation: sandbox Stripe prices are not approved live rates. A quote enquiry is nonbinding. This assistant cannot activate trials. Use existing team-size and location context.","locale":"en","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"647cd2262759ada7f2fbb4d64618ecd0111ee2c4622fa6faf90b8a82505fb2bd","status":"published","updated_at":"2026-11-10 01:29:27.868042+00","expected_hash":"75942ec3a0ba93f0974de82ec533316bb4dd383d08a751304de3d1e1bfcd5d1c","expected_updated_at":"2026-11-12 11:19:24.245557+00"},{"id":"nevora-availability-es","title":"Prueba, configuración, precios y fin de la prueba","url":"https://www.thevelani.com/pages/plans","content":"Reglas confirmadas por Jose el 9 de noviembre de 2026: la prueba estándar de NEVORA es gratuita durante 30 días, sin tarjeta ni cargo automático el día 30. Comienza cuando se provisiona el espacio de trabajo, no al enviar un formulario ni verificar el correo. La configuración estándar cubre hasta 30 empleados. Más de 30 requiere configuración asistida y cotización: Velani revisa la elegibilidad; los equipos aprobados reciben la misma prueba de 30 días sin tarjeta desde la provisión. support@thevelani.com responde a solicitudes de configuración asistida en dos días laborables. No prometas elegibilidad automática, activación instantánea ni fecha de configuración. El registro público de autoservicio aún no se ha lanzado; utiliza https://www.thevelani.com/pages/contact?interest=nevora-demo hasta confirmar una dirección operativa. Al vencer una prueba sin pago, se restringe el uso operativo. El Owner conserva facturación y exportaciones de nómina disponibles; cada empleado conserva sus propios comprobantes disponibles. El fin de la prueba no inicia un plazo de eliminación automática del espacio. No repitas la eliminación antigua en tres días, prometas una futura de 30 días ni almacenamiento indefinido. Las obligaciones de conservación y solicitudes verificadas de eliminación son distintas. La conservación del chat durante 30 días no es la del espacio. Recomienda exportar sin inventar una fecha de eliminación. Las tarifas comerciales requieren confirmación: los precios de prueba de Stripe no son tarifas aprobadas. Una consulta no es vinculante. Este asistente no activa pruebas. Usa el tamaño del equipo y ubicaciones ya indicados.","locale":"es","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"f85abcabaf4d584df0f8070c2803b478daf153f674cc45a2a35e84861064a709","status":"published","updated_at":"2026-11-10 01:29:27.88323+00","expected_hash":"de8e90cfc05e15ae2affb9c75e857cfd4c33608eee3c62ccd4b14d315c482d7e","expected_updated_at":"2026-11-12 11:19:24.251372+00"},{"id":"nevora-overview-en","title":"NEVORA: product purpose and team workflows","url":"https://www.thevelani.com/pages/nevora","content":"NEVORA is Velani''s workforce product for shift teams. Its published product page now advertises availability with workplace setup by the team, not instant self-service signup by this chat. Managers plan shifts and approve hours on the web. Employees view shifts, respond to swaps and request time off on phones. Approved hours feed payroll calculations and pay statements. It works on web, phones and shared tablets, with English or Spanish chosen by each person. Published capabilities do not establish specific integrations, automated legal compliance, guaranteed savings or same-day setup. The website assistant provides advice, not authenticated employer-account operations. The separate trial article contains the current commercial limits.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"aae3742465a1b57fa5a1da299eb5d948b8c5adcef191352d6191029945aff468","status":"published","updated_at":"2026-11-05 14:24:08.323212+00","expected_hash":"aae3742465a1b57fa5a1da299eb5d948b8c5adcef191352d6191029945aff468","expected_updated_at":"2026-11-12 11:19:24.232549+00"},{"id":"nevora-overview-es","title":"NEVORA: propósito del producto y trabajo por turnos","url":"https://www.thevelani.com/pages/nevora","content":"NEVORA es el producto de Velani para equipos por turnos. Su página pública ahora anuncia disponibilidad con configuración por el equipo, no registro instantáneo mediante este chat. Los administradores organizan turnos y aprueban horas en la web. Los empleados consultan turnos, responden a intercambios y solicitan tiempo libre desde teléfonos. Las horas aprobadas alimentan el cálculo de nómina y los comprobantes. Funciona en web, teléfonos y tabletas compartidas, con inglés o español elegido por cada persona. Estas funciones no establecen integraciones específicas, cumplimiento legal automático, ahorros garantizados ni configuración el mismo día. El asistente del sitio orienta, no opera cuentas de empresas. El artículo de prueba contiene los límites comerciales actuales.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"e4c10340de70fb653f3f0c45cbb943adcec6e28b9c26976a52cd390493a39d5e","status":"published","updated_at":"2026-11-05 14:24:08.325336+00","expected_hash":"e4c10340de70fb653f3f0c45cbb943adcec6e28b9c26976a52cd390493a39d5e","expected_updated_at":"2026-11-12 11:19:24.245414+00"},{"id":"nevora-payroll-en","title":"Payroll calculations and employer responsibilities","url":"https://www.thevelani.com/pages/nevora","content":"The described NEVORA payroll workflow calculates payroll from approved hours. A manager reviews the calculations and publishes employee pay statements. NEVORA does not pay employees and does not file payroll taxes; those tasks remain the employer''s responsibility. Do not describe the product as a payroll-payment service, direct-deposit service, tax-filing service or replacement for the employer''s payroll provider unless newly reviewed official documentation expressly confirms that capability. There is no verified list here of supported payroll integrations, export formats, overtime rules, tax jurisdictions or deductions. Ask about the employer''s current approval and payroll process when helpful, and refer detailed compatibility or legal-compliance questions to the team. The website assistant cannot read, calculate from, modify or publish a real employee''s payroll records.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"21cba76793bb38151632f47693029ccf8dc67bb942cf657dfa003a8fa6042765","status":"published","updated_at":"2026-11-05 14:24:08.326774+00","expected_hash":"21cba76793bb38151632f47693029ccf8dc67bb942cf657dfa003a8fa6042765","expected_updated_at":"2026-11-12 11:19:24.247157+00"},{"id":"nevora-payroll-es","title":"Cálculo de nómina y responsabilidades del empleador","url":"https://www.thevelani.com/pages/nevora","content":"El flujo de nómina descrito de NEVORA calcula la nómina a partir de horas aprobadas. Un administrador revisa los cálculos y publica los comprobantes de pago de los empleados. NEVORA no paga a los empleados ni presenta impuestos de nómina; esas tareas siguen siendo responsabilidad del empleador. No se debe presentar el producto como servicio de pago, depósito directo o presentación de impuestos, ni como sustituto del proveedor de nómina, salvo que nueva documentación oficial revisada confirme expresamente esa función. Aquí no hay una lista verificada de integraciones de nómina, formatos de exportación, reglas de horas extras, jurisdicciones fiscales o deducciones. Cuando ayude, conviene preguntar cómo se aprueban y procesan las horas actualmente y remitir dudas específicas de compatibilidad o cumplimiento al equipo. El asistente no puede consultar, modificar ni publicar la nómina real de un trabajador.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"204051131b2ebb40541097feb1a049568f182d4cd5d8616466e494fd20ba0311","status":"published","updated_at":"2026-11-05 14:24:08.328813+00","expected_hash":"204051131b2ebb40541097feb1a049568f182d4cd5d8616466e494fd20ba0311","expected_updated_at":"2026-11-12 11:19:24.247352+00"},{"id":"nevora-rondo-en","title":"Rondo: website advice and planned in-app assistance","url":"https://www.thevelani.com/pages/nevora","content":"Rondo is the name of NEVORA''s AI assistant, and the same name is used for the website adviser, available through \"Ask Rondo\" wherever chat is enabled, including the Shopify preview. Availability in the preview does not mean the chat has been published on the main site. The website Rondo is a product adviser: it explains published information about NEVORA, the free trial, NEVORA Relay and Velani''s websites and apps, helps reason through workflows and points to the right page or contact form. It has no authenticated workforce access and cannot read attendance, rank actual employees, remember priorities across accounts, prepare real schedule changes, approve actions, book meetings, send email or take payments. The in-app owner assistant inside NEVORA is labelled in development on the public product page. Its planned experience includes morning briefings, identifying possible cover, reviewing timecards before payday and remembering owner priorities, with owner approval before changes. The examples use fictional people, not evidence of live capabilities. Do not promise these planned functions as available today. Explain the distinction naturally when asked about Rondo or operational actions.","locale":"en","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"7b61c2ec52be47d576da9b47d21721bfd2e9b376ec3b1a02c3d4e708fd82999e","status":"published","updated_at":"2026-11-05 14:24:08.330861+00","expected_hash":"0ff2eac5b41989c8c7735a04618d6af608651463ac8ec1417ff93b6016ba5851","expected_updated_at":"2026-11-12 11:19:24.24747+00"},{"id":"nevora-rondo-es","title":"Rondo: orientación web y asistencia prevista en la aplicación","url":"https://www.thevelani.com/pages/nevora","content":"Rondo es el nombre del asistente de IA de NEVORA, y el mismo nombre se usa para el asesor del sitio web, disponible mediante \"Ask Rondo\" (\"Pregúntale a Rondo\") donde el chat esté habilitado, incluida la vista previa de Shopify. Que funcione en la vista previa no significa que el chat esté publicado en el sitio principal. El Rondo del sitio web es un asesor de producto: explica la información publicada sobre NEVORA, la prueba gratuita, NEVORA Relay y los sitios web y aplicaciones de Velani, ayuda a razonar sobre flujos de trabajo y señala la página o el formulario de contacto adecuado. No tiene acceso autenticado a datos laborales y no puede leer asistencia, clasificar empleados reales, recordar prioridades entre cuentas, preparar cambios reales de horario, aprobar acciones, reservar reuniones, enviar correos ni cobrar pagos. El asistente para propietarios dentro de NEVORA figura como en desarrollo en la página pública del producto. Su experiencia prevista incluye resúmenes por la mañana, detectar posibles reemplazos, revisar registros de tiempo antes del día de pago y recordar las prioridades del propietario, siempre con su aprobación antes de cambiar algo. Los ejemplos usan personas ficticias y no demuestran funciones disponibles. No prometas estas funciones previstas como disponibles hoy. Explica la diferencia con naturalidad cuando pregunten por Rondo o por acciones operativas.","locale":"es","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"0c1bb85fad0d14455e04c89274074cf2bd9b414966df1e679dd6a20015f80635","status":"published","updated_at":"2026-11-05 14:24:08.332377+00","expected_hash":"e926ca485064fa979814cd2b1000b53abc5ef9bc127bdceeba67dfb59f36e093","expected_updated_at":"2026-11-12 11:19:24.248687+00"},{"id":"nevora-support-en","title":"Employee account help and privacy boundaries","url":"https://www.thevelani.com/pages/nevora-support","content":"Owners, Managers, Leads and Employees normally sign in at their own workplace address with their company-local Employee ID and password. Email verifies registration and supports invitations and recovery; it is not the normal sign-in ID. Each provisioned workplace has its own registered address. Do not direct people to the parked nevora.team apex or invent an address or an email-based workplace finder. The four-digit shared-tablet clock PIN is separate from the portal password. Use Forgot access with Employee ID and registered email for password recovery; contact the manager or Owner if the email or workplace address is unavailable. The workplace administrator handles PIN resets. Employee accounts come from the employer. For personal schedules, timecards or pay statements contact the employer or support@thevelani.com. This website assistant has no access to employer accounts, directories, wages, PINs, passwords, schedules or payroll. It cannot reset credentials, edit punches, approve leave or delete accounts. Never request credentials, government IDs, financial details or employee records in chat. Privacy and account-deletion pages: https://www.thevelani.com/pages/nevora-privacy and https://www.thevelani.com/pages/nevora-account-deletion. Trial expiry starts no automatic workplace-deletion timer; retention duties and verified individual deletion requests are separate. Do not promise indefinite retention. United States/Northern Virginia hosting, encrypted connections and role-based access are product statements, not independent certification. Do not invent SOC 2, HIPAA, labor-law compliance or contractual guarantees.","locale":"en","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"8fe4b3605da37fa5f488b77086f1fc37d276bf887c914cf538834362429a6bcd","status":"published","updated_at":"2026-11-10 01:29:27.885156+00","expected_hash":"cfb557ad1b2743625f90c1b1e851dc5a22dcf29a1caa38a8d13166f1b557f466","expected_updated_at":"2026-11-12 11:19:24.251612+00"},{"id":"nevora-support-es","title":"Ayuda con cuentas de empleados y límites de privacidad","url":"https://www.thevelani.com/pages/nevora-support","content":"Owners, Managers, Leads y Employees normalmente inician sesión en la dirección de su propio espacio con su Employee ID (ID de empleado de esa empresa) y contraseña. El correo verifica el registro y sirve para invitaciones y recuperación; no es el identificador habitual. Cada espacio provisionado tiene su propia dirección registrada. No envíes personas al dominio nevora.team aparcado ni inventes una dirección o un buscador de espacios por correo. El PIN de cuatro dígitos del reloj compartido es distinto de la contraseña. Usa Forgot access con ID de empleado y correo registrado para recuperar la contraseña; consulta al administrador o al Owner si no tienes el correo o la dirección. El administrador del espacio gestiona el restablecimiento del PIN. El empleador proporciona las cuentas. Para horarios, registros de horas o comprobantes personales, contacta al empleador o a support@thevelani.com. Este asistente no accede a cuentas, directorios, salarios, PIN, contraseñas, horarios ni nóminas. No restablece credenciales, modifica fichajes, aprueba permisos ni elimina cuentas. No pidas credenciales, documentos de identidad, datos financieros o expedientes en el chat. Privacidad y eliminación: https://www.thevelani.com/pages/nevora-privacy y https://www.thevelani.com/pages/nevora-account-deletion. El fin de la prueba no inicia eliminación automática del espacio; las obligaciones de conservación y las solicitudes individuales verificadas son distintas. No prometas conservación indefinida. El alojamiento en Estados Unidos/Virginia del Norte, cifrado y permisos por roles son declaraciones del producto, no certificación independiente. No inventes SOC 2, cumplimiento HIPAA o laboral ni garantías contractuales.","locale":"es","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"4537e09ad18a104c5fccf96fc945a9232fcdc712a42280c2bd9d1f48185e1a46","status":"published","updated_at":"2026-11-10 01:29:27.887136+00","expected_hash":"64a33921f7f8bb3267a0b3d53e74f2419ed96a17804b854a4ba737572e7ca84c","expected_updated_at":"2026-11-12 11:19:24.251808+00"},{"id":"nevora-time-clock-en","title":"Shared PIN time clock, languages and demonstration limits","url":"https://www.thevelani.com/pages/nevora","content":"The published NEVORA page offers a public sample time clock. Visitors may enter any four sample digits; the screen clears for the next person. The page says nothing entered in this demonstration is saved or sent. It is a fictional workplace, not real attendance, payroll or account access. Never enter a real employee PIN in the sample. The actual product uses a four-digit PIN on a shared-tablet clock, separate from the portal password. English and Spanish are available, chosen by each person. Managers review real attendance in the authenticated workplace. This assistant cannot clock someone in, generate PINs or create accounts. A requested demonstration may use show_demo with this source, without claiming it has already been opened.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"53c6b6cf9503107ea4473a315b873c1993ca48ce9e1914ae3b043f8d51a401eb","status":"published","updated_at":"2026-11-05 14:24:08.337402+00","expected_hash":"53c6b6cf9503107ea4473a315b873c1993ca48ce9e1914ae3b043f8d51a401eb","expected_updated_at":"2026-11-12 11:19:24.249323+00"},{"id":"nevora-time-clock-es","title":"Reloj compartido con PIN, idiomas y límites de la demostración","url":"https://www.thevelani.com/pages/nevora","content":"La página pública de NEVORA ofrece un reloj de muestra. Se pueden escribir cuatro dígitos de ejemplo y la pantalla se limpia para la siguiente persona. La página indica que nada de lo introducido se guarda ni se envía. Es un espacio ficticio, no asistencia real, nómina ni acceso a cuentas. No se debe usar un PIN real de empleado. El producto utiliza un PIN de cuatro dígitos en una tableta compartida, separado de la contraseña del portal. Cada persona elige inglés o español. Los administradores revisan asistencia real en su espacio autenticado. Este asistente no ficha, genera PIN ni crea cuentas. Si se solicita una demostración, puede usarse show_demo con esta fuente, sin afirmar que ya se abrió.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"552be9b4e42974c7499ec30e6e4974ed269ffa85e2f4a4fa1ed1e3ea89d8d82b","status":"published","updated_at":"2026-11-05 14:24:08.338752+00","expected_hash":"552be9b4e42974c7499ec30e6e4974ed269ffa85e2f4a4fa1ed1e3ea89d8d82b","expected_updated_at":"2026-11-12 11:19:24.24946+00"},{"id":"velani-enquiries-en","title":"Velani, custom development and commercial enquiries","url":"https://www.thevelani.com/pages/contact?interest=nevora","content":"Velani is a brand of VELANI LLC. Alongside NEVORA, its site describes websites, online stores, booking systems, custom web and mobile applications, business systems and integrations; custom project scope and pricing require a discussion with the team. Custom-development information is at https://www.thevelani.com/pages/custom-development and enquiries can use https://www.thevelani.com/pages/contact?interest=custom-software (websites: ?interest=website). NEVORA quote enquiries use https://www.thevelani.com/pages/contact?interest=nevora, free trial requests use ?interest=nevora-demo, and NEVORA Relay waitlist sign-ups use ?interest=relay. After a successful send, the contact page replaces the form with a confirmation that says what happens next; replies come by email from support@thevelani.com, and the published contact page says the team replies within two business days. Velani does not send an automatic confirmation email. A helpful assistant answers the visitor''s product question before suggesting a quote or follow-up. Mentioning an email address in chat does not mean a lead was saved, an email was sent or a meeting was booked; the language model cannot perform these actions and must not claim completion. Do not invent a booking URL or a named sales representative.","locale":"en","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"9ba452b9cdaefc660ccc734fa60d858518686fc214dc26de09b92d8569f19faa","status":"published","updated_at":"2026-11-05 14:24:08.340146+00","expected_hash":"f49b73006a553534b38096249f5a8eb160cfb6da6d984819b7ee99130d1c013d","expected_updated_at":"2026-11-12 11:19:24.250153+00"},{"id":"velani-enquiries-es","title":"Velani, desarrollo a medida y consultas comerciales","url":"https://www.thevelani.com/pages/contact?interest=nevora","content":"Velani es una marca de VELANI LLC. Además de NEVORA, su sitio describe sitios web, tiendas en línea, sistemas de reservas, aplicaciones web y móviles a la medida, sistemas de negocio e integraciones; el alcance y el precio de un proyecto a la medida requieren hablar con el equipo. La información sobre desarrollo a la medida está en https://www.thevelani.com/pages/custom-development y las consultas pueden usar https://www.thevelani.com/pages/contact?interest=custom-software (sitios web: ?interest=website). Las consultas de cotización de NEVORA usan https://www.thevelani.com/pages/contact?interest=nevora, las solicitudes de prueba gratuita usan ?interest=nevora-demo y la lista de espera de NEVORA Relay usa ?interest=relay. Tras un envío correcto, la página de contacto reemplaza el formulario con una confirmación que explica el siguiente paso; las respuestas llegan por correo desde support@thevelani.com, y la página de contacto publicada indica que el equipo responde en un plazo de dos días laborables. Velani no envía un correo de confirmación automático. Un buen asistente responde primero la pregunta del visitante antes de sugerir una cotización o un seguimiento. Mencionar un correo electrónico en el chat no significa que se haya guardado una consulta, enviado un correo o reservado una reunión; el modelo de lenguaje no puede hacer esas acciones y no debe afirmar que se completaron. No inventes un enlace de reservas ni un representante de ventas con nombre.","locale":"es","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"7ba7e5484f1e35f2a55affde0c9577b7f5cf7becb0471ace69082b573dee2f2c","status":"published","updated_at":"2026-11-05 14:24:08.341644+00","expected_hash":"5b01f4d216b48d2531b335eacbe04229a7e8e9c3058bb58a248fc8a97c3e4db5","expected_updated_at":"2026-11-12 11:19:24.250838+00"},{"id":"velani-relay-en","title":"NEVORA Relay: orders, kitchen display and inventory (coming soon)","url":"https://www.thevelani.com/pages/products#relay","content":"NEVORA Relay is a planned Velani product for businesses that take orders, such as cafés, restaurants and counters. The public Products page lists it as coming soon, in design, with no dates yet. It is described as one system for orders entered at the counter and sent to the right preparation screen, a kitchen display where staff accept, prepare and complete orders without paper tickets, and inventory that updates as orders are completed with a warning before stock runs low. Pickup and delivery handoffs and a live dashboard are described as following later. It is described as working on its own and with NEVORA Workforce. Relay is not available to buy or try today; do not quote prices, launch dates, hardware, integrations or payment processing. Visitors can join the waitlist at https://www.thevelani.com/pages/contact?interest=relay with a name and email; joining does not reserve a price or a launch slot.","locale":"en","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"d3a677ea1ac57f316d74d5d0ac00dd1b8fd37b3389a29cfd14004ff6fedc1a2b","status":"published","updated_at":"2026-11-05 14:24:08.343032+00","expected_hash":"d3a677ea1ac57f316d74d5d0ac00dd1b8fd37b3389a29cfd14004ff6fedc1a2b","expected_updated_at":"2026-11-12 11:19:24.251043+00"},{"id":"velani-relay-es","title":"NEVORA Relay: pedidos, pantalla de cocina e inventario (próximamente)","url":"https://www.thevelani.com/pages/products#relay","content":"NEVORA Relay es un producto previsto de Velani para negocios que toman pedidos, como cafeterías, restaurantes y mostradores. La página pública de productos lo presenta como próximamente, en diseño y sin fechas todavía. Se describe como un solo sistema para pedidos tomados en el mostrador y enviados a la pantalla de preparación correcta, una pantalla de cocina donde el personal acepta, prepara y completa pedidos sin tickets de papel, e inventario que se actualiza al completar pedidos con un aviso antes de que se agoten las existencias. Las entregas para recoger y a domicilio y un panel en vivo se describen como pasos posteriores. Se describe como un sistema que funciona por sí solo y con NEVORA Workforce. Relay no se puede comprar ni probar hoy; no indiques precios, fechas de lanzamiento, equipos, integraciones ni procesamiento de pagos. Los visitantes pueden unirse a la lista de espera en https://www.thevelani.com/pages/contact?interest=relay con su nombre y correo; unirse no reserva un precio ni un lugar de lanzamiento.","locale":"es","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"ef443527e9ba5869382b9a13a2bd2a2b78d4bd0afa81e14cc12f49233d32de2b","status":"published","updated_at":"2026-11-05 14:24:08.344365+00","expected_hash":"ef443527e9ba5869382b9a13a2bd2a2b78d4bd0afa81e14cc12f49233d32de2b","expected_updated_at":"2026-11-12 11:19:24.251218+00"}]'::jsonb) AS x(id text,title text,url text,content text,locale text,reviewed_at text,valid_until text,is_core boolean,managed_by text,content_hash text,status text,expected_hash text,expected_updated_at text) ON d.id=x.id WHERE d.content_hash=x.expected_hash AND d.updated_at=x.expected_updated_at::timestamptz AND d.status='published')<>16 THEN RAISE EXCEPTION 'Rollback guard changed'; END IF;
UPDATE knowledge_documents d SET title=x.title,url=x.url,content=x.content,locale=x.locale,reviewed_at=x.reviewed_at::timestamptz,valid_until=x.valid_until::timestamptz,is_core=x.is_core,managed_by=x.managed_by,content_hash=x.content_hash,status=x.status,embedding=CASE WHEN d.content_hash=x.content_hash THEN d.embedding ELSE NULL END,updated_at=clock_timestamp() FROM jsonb_to_recordset('[{"id":"nevora-availability-en","title":"Trial, setup, pricing and end-of-trial choices","url":"https://www.thevelani.com/pages/plans","content":"Jose-confirmed rules, November 9, 2026: NEVORA''s standard trial is free for 30 days with no card and no automatic charge on day 30. It begins when the workplace is provisioned, not at form submission or email verification. Standard setup covers up to 30 employees. Over 30 requires assisted setup and a quote: Velani reviews eligibility; approved teams receive the same 30-day no-card trial starting at provisioning. support@thevelani.com responds to assisted-setup requests within two business days. Do not promise automatic eligibility, instant setup or an activation date. Public self-service signup is not launched yet; use https://www.thevelani.com/pages/contact?interest=nevora-demo until a working signup address is confirmed. At unpaid expiry, operational access is restricted. The Owner retains billing and available payroll exports; employees retain their own available pay statements. Trial expiry starts no automatic workplace-deletion timer. Do not repeat the old three-day deletion claim, promise a future 30-day deletion timer, or promise indefinite storage. Record-retention duties and verified account-deletion requests remain separate. Rondo''s 30-day conversation retention is not workplace retention. Recommend exporting needed records without inventing a deletion deadline. Public commercial prices require confirmation: sandbox Stripe prices are not approved live rates. A quote enquiry is nonbinding. This assistant cannot activate trials. Use existing team-size and location context.","locale":"en","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"647cd2262759ada7f2fbb4d64618ecd0111ee2c4622fa6faf90b8a82505fb2bd","status":"published","updated_at":"2026-11-10 01:29:27.868042+00","expected_hash":"75942ec3a0ba93f0974de82ec533316bb4dd383d08a751304de3d1e1bfcd5d1c","expected_updated_at":"2026-11-12 11:19:24.245557+00"},{"id":"nevora-availability-es","title":"Prueba, configuración, precios y fin de la prueba","url":"https://www.thevelani.com/pages/plans","content":"Reglas confirmadas por Jose el 9 de noviembre de 2026: la prueba estándar de NEVORA es gratuita durante 30 días, sin tarjeta ni cargo automático el día 30. Comienza cuando se provisiona el espacio de trabajo, no al enviar un formulario ni verificar el correo. La configuración estándar cubre hasta 30 empleados. Más de 30 requiere configuración asistida y cotización: Velani revisa la elegibilidad; los equipos aprobados reciben la misma prueba de 30 días sin tarjeta desde la provisión. support@thevelani.com responde a solicitudes de configuración asistida en dos días laborables. No prometas elegibilidad automática, activación instantánea ni fecha de configuración. El registro público de autoservicio aún no se ha lanzado; utiliza https://www.thevelani.com/pages/contact?interest=nevora-demo hasta confirmar una dirección operativa. Al vencer una prueba sin pago, se restringe el uso operativo. El Owner conserva facturación y exportaciones de nómina disponibles; cada empleado conserva sus propios comprobantes disponibles. El fin de la prueba no inicia un plazo de eliminación automática del espacio. No repitas la eliminación antigua en tres días, prometas una futura de 30 días ni almacenamiento indefinido. Las obligaciones de conservación y solicitudes verificadas de eliminación son distintas. La conservación del chat durante 30 días no es la del espacio. Recomienda exportar sin inventar una fecha de eliminación. Las tarifas comerciales requieren confirmación: los precios de prueba de Stripe no son tarifas aprobadas. Una consulta no es vinculante. Este asistente no activa pruebas. Usa el tamaño del equipo y ubicaciones ya indicados.","locale":"es","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"f85abcabaf4d584df0f8070c2803b478daf153f674cc45a2a35e84861064a709","status":"published","updated_at":"2026-11-10 01:29:27.88323+00","expected_hash":"de8e90cfc05e15ae2affb9c75e857cfd4c33608eee3c62ccd4b14d315c482d7e","expected_updated_at":"2026-11-12 11:19:24.251372+00"},{"id":"nevora-overview-en","title":"NEVORA: product purpose and team workflows","url":"https://www.thevelani.com/pages/nevora","content":"NEVORA is Velani''s workforce product for shift teams. Its published product page now advertises availability with workplace setup by the team, not instant self-service signup by this chat. Managers plan shifts and approve hours on the web. Employees view shifts, respond to swaps and request time off on phones. Approved hours feed payroll calculations and pay statements. It works on web, phones and shared tablets, with English or Spanish chosen by each person. Published capabilities do not establish specific integrations, automated legal compliance, guaranteed savings or same-day setup. The website assistant provides advice, not authenticated employer-account operations. The separate trial article contains the current commercial limits.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"aae3742465a1b57fa5a1da299eb5d948b8c5adcef191352d6191029945aff468","status":"published","updated_at":"2026-11-05 14:24:08.323212+00","expected_hash":"aae3742465a1b57fa5a1da299eb5d948b8c5adcef191352d6191029945aff468","expected_updated_at":"2026-11-12 11:19:24.232549+00"},{"id":"nevora-overview-es","title":"NEVORA: propósito del producto y trabajo por turnos","url":"https://www.thevelani.com/pages/nevora","content":"NEVORA es el producto de Velani para equipos por turnos. Su página pública ahora anuncia disponibilidad con configuración por el equipo, no registro instantáneo mediante este chat. Los administradores organizan turnos y aprueban horas en la web. Los empleados consultan turnos, responden a intercambios y solicitan tiempo libre desde teléfonos. Las horas aprobadas alimentan el cálculo de nómina y los comprobantes. Funciona en web, teléfonos y tabletas compartidas, con inglés o español elegido por cada persona. Estas funciones no establecen integraciones específicas, cumplimiento legal automático, ahorros garantizados ni configuración el mismo día. El asistente del sitio orienta, no opera cuentas de empresas. El artículo de prueba contiene los límites comerciales actuales.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"e4c10340de70fb653f3f0c45cbb943adcec6e28b9c26976a52cd390493a39d5e","status":"published","updated_at":"2026-11-05 14:24:08.325336+00","expected_hash":"e4c10340de70fb653f3f0c45cbb943adcec6e28b9c26976a52cd390493a39d5e","expected_updated_at":"2026-11-12 11:19:24.245414+00"},{"id":"nevora-payroll-en","title":"Payroll calculations and employer responsibilities","url":"https://www.thevelani.com/pages/nevora","content":"The described NEVORA payroll workflow calculates payroll from approved hours. A manager reviews the calculations and publishes employee pay statements. NEVORA does not pay employees and does not file payroll taxes; those tasks remain the employer''s responsibility. Do not describe the product as a payroll-payment service, direct-deposit service, tax-filing service or replacement for the employer''s payroll provider unless newly reviewed official documentation expressly confirms that capability. There is no verified list here of supported payroll integrations, export formats, overtime rules, tax jurisdictions or deductions. Ask about the employer''s current approval and payroll process when helpful, and refer detailed compatibility or legal-compliance questions to the team. The website assistant cannot read, calculate from, modify or publish a real employee''s payroll records.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"21cba76793bb38151632f47693029ccf8dc67bb942cf657dfa003a8fa6042765","status":"published","updated_at":"2026-11-05 14:24:08.326774+00","expected_hash":"21cba76793bb38151632f47693029ccf8dc67bb942cf657dfa003a8fa6042765","expected_updated_at":"2026-11-12 11:19:24.247157+00"},{"id":"nevora-payroll-es","title":"Cálculo de nómina y responsabilidades del empleador","url":"https://www.thevelani.com/pages/nevora","content":"El flujo de nómina descrito de NEVORA calcula la nómina a partir de horas aprobadas. Un administrador revisa los cálculos y publica los comprobantes de pago de los empleados. NEVORA no paga a los empleados ni presenta impuestos de nómina; esas tareas siguen siendo responsabilidad del empleador. No se debe presentar el producto como servicio de pago, depósito directo o presentación de impuestos, ni como sustituto del proveedor de nómina, salvo que nueva documentación oficial revisada confirme expresamente esa función. Aquí no hay una lista verificada de integraciones de nómina, formatos de exportación, reglas de horas extras, jurisdicciones fiscales o deducciones. Cuando ayude, conviene preguntar cómo se aprueban y procesan las horas actualmente y remitir dudas específicas de compatibilidad o cumplimiento al equipo. El asistente no puede consultar, modificar ni publicar la nómina real de un trabajador.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"204051131b2ebb40541097feb1a049568f182d4cd5d8616466e494fd20ba0311","status":"published","updated_at":"2026-11-05 14:24:08.328813+00","expected_hash":"204051131b2ebb40541097feb1a049568f182d4cd5d8616466e494fd20ba0311","expected_updated_at":"2026-11-12 11:19:24.247352+00"},{"id":"nevora-rondo-en","title":"Rondo: website advice and planned in-app assistance","url":"https://www.thevelani.com/pages/nevora","content":"Rondo is the name of NEVORA''s AI assistant, and the same name is used for the website adviser, available through \"Ask Rondo\" wherever chat is enabled, including the Shopify preview. Availability in the preview does not mean the chat has been published on the main site. The website Rondo is a product adviser: it explains published information about NEVORA, the free trial, NEVORA Relay and Velani''s websites and apps, helps reason through workflows and points to the right page or contact form. It has no authenticated workforce access and cannot read attendance, rank actual employees, remember priorities across accounts, prepare real schedule changes, approve actions, book meetings, send email or take payments. The in-app owner assistant inside NEVORA is labelled in development on the public product page. Its planned experience includes morning briefings, identifying possible cover, reviewing timecards before payday and remembering owner priorities, with owner approval before changes. The examples use fictional people, not evidence of live capabilities. Do not promise these planned functions as available today. Explain the distinction naturally when asked about Rondo or operational actions.","locale":"en","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"7b61c2ec52be47d576da9b47d21721bfd2e9b376ec3b1a02c3d4e708fd82999e","status":"published","updated_at":"2026-11-05 14:24:08.330861+00","expected_hash":"0ff2eac5b41989c8c7735a04618d6af608651463ac8ec1417ff93b6016ba5851","expected_updated_at":"2026-11-12 11:19:24.24747+00"},{"id":"nevora-rondo-es","title":"Rondo: orientación web y asistencia prevista en la aplicación","url":"https://www.thevelani.com/pages/nevora","content":"Rondo es el nombre del asistente de IA de NEVORA, y el mismo nombre se usa para el asesor del sitio web, disponible mediante \"Ask Rondo\" (\"Pregúntale a Rondo\") donde el chat esté habilitado, incluida la vista previa de Shopify. Que funcione en la vista previa no significa que el chat esté publicado en el sitio principal. El Rondo del sitio web es un asesor de producto: explica la información publicada sobre NEVORA, la prueba gratuita, NEVORA Relay y los sitios web y aplicaciones de Velani, ayuda a razonar sobre flujos de trabajo y señala la página o el formulario de contacto adecuado. No tiene acceso autenticado a datos laborales y no puede leer asistencia, clasificar empleados reales, recordar prioridades entre cuentas, preparar cambios reales de horario, aprobar acciones, reservar reuniones, enviar correos ni cobrar pagos. El asistente para propietarios dentro de NEVORA figura como en desarrollo en la página pública del producto. Su experiencia prevista incluye resúmenes por la mañana, detectar posibles reemplazos, revisar registros de tiempo antes del día de pago y recordar las prioridades del propietario, siempre con su aprobación antes de cambiar algo. Los ejemplos usan personas ficticias y no demuestran funciones disponibles. No prometas estas funciones previstas como disponibles hoy. Explica la diferencia con naturalidad cuando pregunten por Rondo o por acciones operativas.","locale":"es","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"0c1bb85fad0d14455e04c89274074cf2bd9b414966df1e679dd6a20015f80635","status":"published","updated_at":"2026-11-05 14:24:08.332377+00","expected_hash":"e926ca485064fa979814cd2b1000b53abc5ef9bc127bdceeba67dfb59f36e093","expected_updated_at":"2026-11-12 11:19:24.248687+00"},{"id":"nevora-support-en","title":"Employee account help and privacy boundaries","url":"https://www.thevelani.com/pages/nevora-support","content":"Owners, Managers, Leads and Employees normally sign in at their own workplace address with their company-local Employee ID and password. Email verifies registration and supports invitations and recovery; it is not the normal sign-in ID. Each provisioned workplace has its own registered address. Do not direct people to the parked nevora.team apex or invent an address or an email-based workplace finder. The four-digit shared-tablet clock PIN is separate from the portal password. Use Forgot access with Employee ID and registered email for password recovery; contact the manager or Owner if the email or workplace address is unavailable. The workplace administrator handles PIN resets. Employee accounts come from the employer. For personal schedules, timecards or pay statements contact the employer or support@thevelani.com. This website assistant has no access to employer accounts, directories, wages, PINs, passwords, schedules or payroll. It cannot reset credentials, edit punches, approve leave or delete accounts. Never request credentials, government IDs, financial details or employee records in chat. Privacy and account-deletion pages: https://www.thevelani.com/pages/nevora-privacy and https://www.thevelani.com/pages/nevora-account-deletion. Trial expiry starts no automatic workplace-deletion timer; retention duties and verified individual deletion requests are separate. Do not promise indefinite retention. United States/Northern Virginia hosting, encrypted connections and role-based access are product statements, not independent certification. Do not invent SOC 2, HIPAA, labor-law compliance or contractual guarantees.","locale":"en","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"8fe4b3605da37fa5f488b77086f1fc37d276bf887c914cf538834362429a6bcd","status":"published","updated_at":"2026-11-10 01:29:27.885156+00","expected_hash":"cfb557ad1b2743625f90c1b1e851dc5a22dcf29a1caa38a8d13166f1b557f466","expected_updated_at":"2026-11-12 11:19:24.251612+00"},{"id":"nevora-support-es","title":"Ayuda con cuentas de empleados y límites de privacidad","url":"https://www.thevelani.com/pages/nevora-support","content":"Owners, Managers, Leads y Employees normalmente inician sesión en la dirección de su propio espacio con su Employee ID (ID de empleado de esa empresa) y contraseña. El correo verifica el registro y sirve para invitaciones y recuperación; no es el identificador habitual. Cada espacio provisionado tiene su propia dirección registrada. No envíes personas al dominio nevora.team aparcado ni inventes una dirección o un buscador de espacios por correo. El PIN de cuatro dígitos del reloj compartido es distinto de la contraseña. Usa Forgot access con ID de empleado y correo registrado para recuperar la contraseña; consulta al administrador o al Owner si no tienes el correo o la dirección. El administrador del espacio gestiona el restablecimiento del PIN. El empleador proporciona las cuentas. Para horarios, registros de horas o comprobantes personales, contacta al empleador o a support@thevelani.com. Este asistente no accede a cuentas, directorios, salarios, PIN, contraseñas, horarios ni nóminas. No restablece credenciales, modifica fichajes, aprueba permisos ni elimina cuentas. No pidas credenciales, documentos de identidad, datos financieros o expedientes en el chat. Privacidad y eliminación: https://www.thevelani.com/pages/nevora-privacy y https://www.thevelani.com/pages/nevora-account-deletion. El fin de la prueba no inicia eliminación automática del espacio; las obligaciones de conservación y las solicitudes individuales verificadas son distintas. No prometas conservación indefinida. El alojamiento en Estados Unidos/Virginia del Norte, cifrado y permisos por roles son declaraciones del producto, no certificación independiente. No inventes SOC 2, cumplimiento HIPAA o laboral ni garantías contractuales.","locale":"es","reviewed_at":"2026-11-09 00:00:00+00","valid_until":"2026-12-09 23:59:59.999+00","is_core":true,"managed_by":"seed","content_hash":"4537e09ad18a104c5fccf96fc945a9232fcdc712a42280c2bd9d1f48185e1a46","status":"published","updated_at":"2026-11-10 01:29:27.887136+00","expected_hash":"64a33921f7f8bb3267a0b3d53e74f2419ed96a17804b854a4ba737572e7ca84c","expected_updated_at":"2026-11-12 11:19:24.251808+00"},{"id":"nevora-time-clock-en","title":"Shared PIN time clock, languages and demonstration limits","url":"https://www.thevelani.com/pages/nevora","content":"The published NEVORA page offers a public sample time clock. Visitors may enter any four sample digits; the screen clears for the next person. The page says nothing entered in this demonstration is saved or sent. It is a fictional workplace, not real attendance, payroll or account access. Never enter a real employee PIN in the sample. The actual product uses a four-digit PIN on a shared-tablet clock, separate from the portal password. English and Spanish are available, chosen by each person. Managers review real attendance in the authenticated workplace. This assistant cannot clock someone in, generate PINs or create accounts. A requested demonstration may use show_demo with this source, without claiming it has already been opened.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"53c6b6cf9503107ea4473a315b873c1993ca48ce9e1914ae3b043f8d51a401eb","status":"published","updated_at":"2026-11-05 14:24:08.337402+00","expected_hash":"53c6b6cf9503107ea4473a315b873c1993ca48ce9e1914ae3b043f8d51a401eb","expected_updated_at":"2026-11-12 11:19:24.249323+00"},{"id":"nevora-time-clock-es","title":"Reloj compartido con PIN, idiomas y límites de la demostración","url":"https://www.thevelani.com/pages/nevora","content":"La página pública de NEVORA ofrece un reloj de muestra. Se pueden escribir cuatro dígitos de ejemplo y la pantalla se limpia para la siguiente persona. La página indica que nada de lo introducido se guarda ni se envía. Es un espacio ficticio, no asistencia real, nómina ni acceso a cuentas. No se debe usar un PIN real de empleado. El producto utiliza un PIN de cuatro dígitos en una tableta compartida, separado de la contraseña del portal. Cada persona elige inglés o español. Los administradores revisan asistencia real en su espacio autenticado. Este asistente no ficha, genera PIN ni crea cuentas. Si se solicita una demostración, puede usarse show_demo con esta fuente, sin afirmar que ya se abrió.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"552be9b4e42974c7499ec30e6e4974ed269ffa85e2f4a4fa1ed1e3ea89d8d82b","status":"published","updated_at":"2026-11-05 14:24:08.338752+00","expected_hash":"552be9b4e42974c7499ec30e6e4974ed269ffa85e2f4a4fa1ed1e3ea89d8d82b","expected_updated_at":"2026-11-12 11:19:24.24946+00"},{"id":"velani-enquiries-en","title":"Velani, custom development and commercial enquiries","url":"https://www.thevelani.com/pages/contact?interest=nevora","content":"Velani is a brand of VELANI LLC. Alongside NEVORA, its site describes websites, online stores, booking systems, custom web and mobile applications, business systems and integrations; custom project scope and pricing require a discussion with the team. Custom-development information is at https://www.thevelani.com/pages/custom-development and enquiries can use https://www.thevelani.com/pages/contact?interest=custom-software (websites: ?interest=website). NEVORA quote enquiries use https://www.thevelani.com/pages/contact?interest=nevora, free trial requests use ?interest=nevora-demo, and NEVORA Relay waitlist sign-ups use ?interest=relay. After a successful send, the contact page replaces the form with a confirmation that says what happens next; replies come by email from support@thevelani.com, and the published contact page says the team replies within two business days. Velani does not send an automatic confirmation email. A helpful assistant answers the visitor''s product question before suggesting a quote or follow-up. Mentioning an email address in chat does not mean a lead was saved, an email was sent or a meeting was booked; the language model cannot perform these actions and must not claim completion. Do not invent a booking URL or a named sales representative.","locale":"en","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"9ba452b9cdaefc660ccc734fa60d858518686fc214dc26de09b92d8569f19faa","status":"published","updated_at":"2026-11-05 14:24:08.340146+00","expected_hash":"f49b73006a553534b38096249f5a8eb160cfb6da6d984819b7ee99130d1c013d","expected_updated_at":"2026-11-12 11:19:24.250153+00"},{"id":"velani-enquiries-es","title":"Velani, desarrollo a medida y consultas comerciales","url":"https://www.thevelani.com/pages/contact?interest=nevora","content":"Velani es una marca de VELANI LLC. Además de NEVORA, su sitio describe sitios web, tiendas en línea, sistemas de reservas, aplicaciones web y móviles a la medida, sistemas de negocio e integraciones; el alcance y el precio de un proyecto a la medida requieren hablar con el equipo. La información sobre desarrollo a la medida está en https://www.thevelani.com/pages/custom-development y las consultas pueden usar https://www.thevelani.com/pages/contact?interest=custom-software (sitios web: ?interest=website). Las consultas de cotización de NEVORA usan https://www.thevelani.com/pages/contact?interest=nevora, las solicitudes de prueba gratuita usan ?interest=nevora-demo y la lista de espera de NEVORA Relay usa ?interest=relay. Tras un envío correcto, la página de contacto reemplaza el formulario con una confirmación que explica el siguiente paso; las respuestas llegan por correo desde support@thevelani.com, y la página de contacto publicada indica que el equipo responde en un plazo de dos días laborables. Velani no envía un correo de confirmación automático. Un buen asistente responde primero la pregunta del visitante antes de sugerir una cotización o un seguimiento. Mencionar un correo electrónico en el chat no significa que se haya guardado una consulta, enviado un correo o reservado una reunión; el modelo de lenguaje no puede hacer esas acciones y no debe afirmar que se completaron. No inventes un enlace de reservas ni un representante de ventas con nombre.","locale":"es","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"7ba7e5484f1e35f2a55affde0c9577b7f5cf7becb0471ace69082b573dee2f2c","status":"published","updated_at":"2026-11-05 14:24:08.341644+00","expected_hash":"5b01f4d216b48d2531b335eacbe04229a7e8e9c3058bb58a248fc8a97c3e4db5","expected_updated_at":"2026-11-12 11:19:24.250838+00"},{"id":"velani-relay-en","title":"NEVORA Relay: orders, kitchen display and inventory (coming soon)","url":"https://www.thevelani.com/pages/products#relay","content":"NEVORA Relay is a planned Velani product for businesses that take orders, such as cafés, restaurants and counters. The public Products page lists it as coming soon, in design, with no dates yet. It is described as one system for orders entered at the counter and sent to the right preparation screen, a kitchen display where staff accept, prepare and complete orders without paper tickets, and inventory that updates as orders are completed with a warning before stock runs low. Pickup and delivery handoffs and a live dashboard are described as following later. It is described as working on its own and with NEVORA Workforce. Relay is not available to buy or try today; do not quote prices, launch dates, hardware, integrations or payment processing. Visitors can join the waitlist at https://www.thevelani.com/pages/contact?interest=relay with a name and email; joining does not reserve a price or a launch slot.","locale":"en","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"d3a677ea1ac57f316d74d5d0ac00dd1b8fd37b3389a29cfd14004ff6fedc1a2b","status":"published","updated_at":"2026-11-05 14:24:08.343032+00","expected_hash":"d3a677ea1ac57f316d74d5d0ac00dd1b8fd37b3389a29cfd14004ff6fedc1a2b","expected_updated_at":"2026-11-12 11:19:24.251043+00"},{"id":"velani-relay-es","title":"NEVORA Relay: pedidos, pantalla de cocina e inventario (próximamente)","url":"https://www.thevelani.com/pages/products#relay","content":"NEVORA Relay es un producto previsto de Velani para negocios que toman pedidos, como cafeterías, restaurantes y mostradores. La página pública de productos lo presenta como próximamente, en diseño y sin fechas todavía. Se describe como un solo sistema para pedidos tomados en el mostrador y enviados a la pantalla de preparación correcta, una pantalla de cocina donde el personal acepta, prepara y completa pedidos sin tickets de papel, e inventario que se actualiza al completar pedidos con un aviso antes de que se agoten las existencias. Las entregas para recoger y a domicilio y un panel en vivo se describen como pasos posteriores. Se describe como un sistema que funciona por sí solo y con NEVORA Workforce. Relay no se puede comprar ni probar hoy; no indiques precios, fechas de lanzamiento, equipos, integraciones ni procesamiento de pagos. Los visitantes pueden unirse a la lista de espera en https://www.thevelani.com/pages/contact?interest=relay con su nombre y correo; unirse no reserva un precio ni un lugar de lanzamiento.","locale":"es","reviewed_at":"2026-11-05 00:00:00+00","valid_until":"2026-12-05 23:59:59.999+00","is_core":false,"managed_by":"seed","content_hash":"ef443527e9ba5869382b9a13a2bd2a2b78d4bd0afa81e14cc12f49233d32de2b","status":"published","updated_at":"2026-11-05 14:24:08.344365+00","expected_hash":"ef443527e9ba5869382b9a13a2bd2a2b78d4bd0afa81e14cc12f49233d32de2b","expected_updated_at":"2026-11-12 11:19:24.251218+00"}]'::jsonb) AS x(id text,title text,url text,content text,locale text,reviewed_at text,valid_until text,is_core boolean,managed_by text,content_hash text,status text,expected_hash text,expected_updated_at text) WHERE d.id=x.id;GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>16 THEN RAISE EXCEPTION 'Unexpected rollback rows';END IF;END $rollback$;
